const item = $input.first().json.body || $input.first().json;

const batchId = item.batchId || 'BATCH-' + Date.now();
const uploadedBy = item.uploadedBy || 'Admin';
const users = item.users || [];
const totalRows = users.length || item.totalRows || 0;

const prompt = `You are the Chief Data Architect & Security Gatekeeper for Community Bulk Onboarding in Mana Community App.
Analyze the following batch of ${totalRows} resident / member records submitted for bulk CSV/Excel database import.
Identify privilege escalation risks, flat occupancy collisions, malformed phone/email contacts, and data anomalies.

Imported Batch Sample (First 30 rows):
${JSON.stringify(users.slice(0, 30), null, 2)}

Audit Requirements:
1. PRIVILEGE ESCALATION GUARD: Flag any row assigning elevated roles ('admin', 'superadmin', 'committee', 'security_lead') in a bulk file without explicit dual-approval flags.
2. FLAT OCCUPANCY COLLISION: Detect if multiple unrelated families or conflicting roles are assigned to the exact same flat/unit in this batch.
3. DATA FORMAT VALIDITY: Identify missing names, malformed phones (non-10 digit / missing international code), throwaway emails, or placeholder values ("test", "asdf").
4. Provide clean counts and recommended automated sanitizations.

Respond ONLY with a valid JSON object matching this schema:
{
  "batchStatus": "READY_TO_IMPORT" | "REQUIRES_APPROVAL" | "BLOCKED_HIGH_RISK",
  "cleanRowsCount": number,
  "flaggedRowsCount": number,
  "escalationRisksDetected": [
    { "row": number, "user": string, "assignedRole": string, "reason": string }
  ],
  "flatCollisions": [
    { "flatUnit": string, "rows": number[], "users": string[] }
  ],
  "sanitizedSuggestions": [
    { "row": number, "field": string, "original": string, "suggested": string }
  ],
  "executiveSummary": "Concise summary for the administrator before they commit this batch to the production database"
}`;

return [{
  json: {
    batchId,
    totalRows,
    prompt
  }
}];

const geminiResponse = $input.first().json;
let parsed = {};

try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsed = JSON.parse(rawText);
} catch (err) {
  parsed = {
    batchStatus: "REQUIRES_APPROVAL",
    cleanRowsCount: 0,
    flaggedRowsCount: 0,
    escalationRisksDetected: [],
    flatCollisions: [],
    sanitizedSuggestions: [],
    executiveSummary: "Batch parsing completed with standard rule checks; manual committee confirmation recommended."
  };
}

const meta = $('Prepare AI Prompt').first().json;

return [{
  json: {
    success: true,
    batchId: meta.batchId,
    totalRows: meta.totalRows,
    evaluatedAt: new Date().toISOString(),
    audit: parsed
  }
}];
